/* Play season: reveal results generated by the exact same whole-season simulator, one round at a time. */
(function () {
    let preparedResults = null;

    function cloneMatch(match) {
        return {
            round: Number(match.round),
            opponent: match.opponent,
            home: !!match.home,
            gf: Number(match.gf),
            ga: Number(match.ga),
            scorers: Array.isArray(match.scorers)
                ? match.scorers.map(s => ({ ...s }))
                : []
        };
    }

    function prepareResults() {
        if (preparedResults) return preparedResults;
        const originalRenderFinalSeason = window.renderFinalSeason;
        try {
            window.renderFinalSeason = function () {};
            window.simulateWholeSeason();
            preparedResults = (seasonGameState.widzewResults || []).map(cloneMatch);
        } finally {
            window.renderFinalSeason = originalRenderFinalSeason;
        }

        seasonGameState.widzewResults = [];
        seasonGameState.scorers = {};
        return preparedResults;
    }

    function scorerClass(scorer) {
        return scorer && scorer.type === "opponent"
            ? "scorer-opponent"
            : "scorer-widzew";
    }

    function scorerName(scorer) {
        if (!scorer) return "";
        if (scorer.type === "opponent") return "Przeciwnik";
        if (scorer.type === "own") return "Samobój";
        return scorer.name || "Zawodnik Widzewa";
    }

    function decorateVisibleScorers(match) {
        const containers = document.querySelectorAll(".match-scorers");
        containers.forEach(container => {
            container.innerHTML = "";
        });

        if (!match || !Array.isArray(match.scorers) || !match.scorers.length) return;

        const container = document.querySelector(".round-match.widzew-match .match-scorers");
        if (!container) return;

        // Każdy gol dostaje osobny wpis. Nie grupujemy strzelców — jeśli zawodnik
        // strzeli dwa gole, pojawią się dwie pozycje z dwiema minutami.
        container.innerHTML = match.scorers
            .slice()
            .sort((a, b) => Number(a.minute || 0) - Number(b.minute || 0))
            .map(s => {
                const minute = Math.max(1, Math.min(90, Number(s.minute) || 1));
                return `<span class="${scorerClass(s)}">${minute}' ${seasonSafe(scorerName(s))}</span>`;
            })
            .join("");
    }

    function addScorerStyles() {
        if (document.getElementById("seasonScorerFixStyles")) return;
        const style = document.createElement("style");
        style.id = "seasonScorerFixStyles";
        style.textContent = `
            .match-scorers {
                display: flex;
                flex-direction: column;
                align-items: center;
                gap: 3px;
                margin-top: 7px;
                font-size: 13px;
                font-weight: 800;
                line-height: 1.25;
            }
            .match-scorers span.scorer-widzew {
                color: #39d353;
            }
            .match-scorers span.scorer-opponent {
                color: #ff4d4f;
            }
        `;
        document.head.appendChild(style);
    }

    function revealCurrentRound() {
        const round = Number(seasonGameState.currentRound);
        if ((seasonGameState.widzewResults || []).some(m => Number(m.round) === round)) return;

        const match = prepareResults().find(m => Number(m.round) === round);
        if (!match) return;

        const revealed = cloneMatch(match);
        seasonGameState.widzewResults.push(revealed);
        if (typeof updateTopScorersFromMatch === "function") {
            updateTopScorersFromMatch(revealed);
        }
        if (typeof renderPlayableSeason === "function") {
            renderPlayableSeason();
        }
        decorateVisibleScorers(revealed);
    }

    addScorerStyles();

    const originalInitSeasonMode = window.initSeasonMode;
    if (typeof originalInitSeasonMode === "function") {
        window.initSeasonMode = async function (mode) {
            preparedResults = null;
            const result = await originalInitSeasonMode.call(this, mode);
            if (mode !== "play") preparedResults = null;
            return result;
        };
    }

    window.simulateCurrentWidzewMatch = revealCurrentRound;

    // "ZAGRAJ MECZ" zostawiamy na później. Na tym etapie kliknięcie nie może
    // uruchamiać symulacji. Tylko "SYMULUJ MECZ" odsłania gotowy wynik kolejki.
    document.addEventListener("click", function (event) {
        const button = event.target && event.target.closest
            ? event.target.closest("#playMatchButton, #simulateMatchButton")
            : null;
        if (!button) return;

        event.preventDefault();
        event.stopImmediatePropagation();

        if (button.id === "simulateMatchButton") {
            revealCurrentRound();
        }
        // playMatchButton celowo nic teraz nie robi.
    }, true);
})();
